package dev.branched.compat.adapter;

import dev.branched.compat.AbstractModAdapter;
import dev.branched.species.CompatibilityLevel;

/**
 * The Twilight Forest 4.3.2508. Magic trees (mining/sorting/time/
 * transformation) have configured features but no placed features: they are
 * generated by code/structures. They must never be silently replaced.
 */
public final class TwilightForestAdapter extends AbstractModAdapter {
    public TwilightForestAdapter() {
        super("twilightforest", "The Twilight Forest", "4.3.2508", CompatibilityLevel.STATIC_NORMAL);

        feature("twilightforest:tree/twilight_oak_tree", "twilightforest:twilight_oak", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/large_twilight_oak_tree", "twilightforest:twilight_oak", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/darkwood_tree", "twilightforest:dark", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/mangrove_tree", "twilightforest:mangrove", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/forest_canopy_oak_tree", "twilightforest:canopy", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/swampy_oak_tree", "twilightforest:twilight_oak", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/dead_canopy_tree", "twilightforest:canopy", CompatibilityLevel.STATIC_NORMAL);
        feature("twilightforest:tree/hollow_oak", "twilightforest:twilight_oak", CompatibilityLevel.SPECIAL_PRESERVE,
                "hollow tree structure with interior spawner/loot");
        feature("twilightforest:hollow_stump", "twilightforest:twilight_oak", CompatibilityLevel.SPECIAL_PRESERVE,
                "hollow stump structure");
        feature("twilightforest:tree/mining_tree", "twilightforest:mining", CompatibilityLevel.SPECIAL_PRESERVE,
                "configured-only magic tree; generated by code/structure");
        feature("twilightforest:tree/sorting_tree", "twilightforest:sorting", CompatibilityLevel.SPECIAL_PRESERVE,
                "configured-only magic tree; generated by code/structure");
        feature("twilightforest:tree/time_tree", "twilightforest:time", CompatibilityLevel.SPECIAL_PRESERVE,
                "configured-only magic tree; generated by code/structure");
        feature("twilightforest:tree/transformation_tree", "twilightforest:transformation", CompatibilityLevel.SPECIAL_PRESERVE,
                "configured-only magic tree; generated by code/structure");
        feature("twilightforest:mushroom/canopy_mushrooms_dense", "twilightforest:canopy_mushroom", CompatibilityLevel.SPECIAL_PRESERVE,
                "mushroom canopy generated by custom feature");
    }
}
